func (n *sros) setupComponentNodes() error {
	if !n.isDistributedBaseNode() {
		return nil
	}

	n.netnsNode = new(clabnodes.NetnsHolder)
	if err := n.netnsNode.Init(
		n.newNetnsConfig(),
